/* eslint-disable @typescript-eslint/no-explicit-any */
'use client'

import * as React from 'react'
import {
  useReactTable,
  getCoreRowModel,
  getPaginationRowModel,
  ColumnDef,
  flexRender,
} from '@tanstack/react-table'
import Image from 'next/image'
import { useGetOrders } from '@/lib/handleAllGetRequests'
import { useOrderStore } from '@/store/store'
import TableSkeleton from '@/components/reusable/TableSkeleton'
import ErrorState from '@/components/reusable/ErrorState'

// Column Definition
const columns: ColumnDef<any>[] = [
  {
    header: 'Customer',
    accessorFn: (row) => row?.buyer?.name || 'N/A',
  },
  {
    header: 'Products',
    cell: ({ row }) => {
      const items = row.original.items || []

      return (
        <div className="flex flex-col gap-3">
          {items.map((item: any, index: number) => {
            const product = item.product
            const imgSrc = product?.images?.[0] || '/images/no-image.png'
            const title = product?.title || 'Unknown Product'

            return (
              <div key={index} className="flex items-center gap-2">
                <div className="w-[80px] h-[60px] relative">
                  <Image
                    src={imgSrc}
                    alt={title}
                    fill
                    className="rounded-lg object-cover"
                  />
                </div>
                <div className="flex flex-col">
                  <span className="font-medium text-sm text-[#272727]">
                    {title}
                  </span>
                  <span className="text-xs text-[#595959]">
                    Qty: {item.quantity} × ${item.unitPrice}
                  </span>
                </div>
              </div>
            )
          })}
        </div>
      )
    },
  },
  {
    header: 'Order ID',
    accessorFn: (row) => row.orderNumber || 'N/A',
  },
  {
    header: 'Total Price',
    accessorFn: (row) => `$${row.total?.toFixed(2)}`,
  },
  {
    header: 'Date',
    accessorFn: (row) =>
      new Date(row.createdAt).toLocaleString('en-US', {
        dateStyle: 'short',
        timeStyle: 'short',
      }),
  },
  {
    header: 'Status',
    accessorFn: (row) => row.status || 'N/A',
  },
]

export default function SalesHistoryTable() {
  const { data, isLoading, isError } = useGetOrders()
  const { orders, setOrders } = useOrderStore()

  // Sync fetched data into Zustand store
  React.useEffect(() => {
    if (data?.data) {
      setOrders(data.data)
    }
  }, [data, setOrders])

  const table = useReactTable({
    data: orders,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    initialState: {
      pagination: {
        pageSize: 6,
      },
    },
  })

  console.log('orders: ', orders)

  if (isLoading) return <TableSkeleton />
  if (isError) return <ErrorState message="Failed to load the Order History" />

  return (
    <div className="bg-transparent border rounded-lg">
      <table className="w-full text-left">
        <thead className="bg-transparent">
          {table.getHeaderGroups().map((headerGroup) => (
            <tr key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <th
                  key={header.id}
                  className="px-4 py-3 text-base font-medium text-[#272727]"
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext()
                  )}
                </th>
              ))}
            </tr>
          ))}
        </thead>
        {/* this is a table */}
        <tbody>
          {table.getRowModel().rows.map((row) => (
            <tr key={row.id} className="border-t">
              {row.getVisibleCells().map((cell) => (
                <td
                  key={cell.id}
                  className="px-4 py-3 text-base text-[#636262]"
                >
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>

      {/* Pagination */}
      <div className="flex items-center justify-between bg-[#ffffff] border-t px-8 py-3 text-sm">
        <div className="text-[#707070] text-base font-medium">
          Showing{' '}
          {table.getState().pagination.pageIndex *
            table.getState().pagination.pageSize +
            1}{' '}
          to{' '}
          {Math.min(
            (table.getState().pagination.pageIndex + 1) *
              table.getState().pagination.pageSize,
            orders.length
          )}{' '}
          of {orders.length} results
        </div>

        {/* numbered pagination with < and > */}
        <div className="flex items-center gap-2">
          <button
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
            className={`w-[40px] h-[40px] rounded-md text-white text-sm font-medium
              ${
                table.getCanPreviousPage()
                  ? 'bg-[#797068]'
                  : 'bg-gray-300 cursor-not-allowed'
              }`}
          >
            {'<'}
          </button>

          {Array.from({ length: table.getPageCount() }, (_, i) => {
            const isActive = table.getState().pagination.pageIndex === i
            return (
              <button
                key={i}
                onClick={() => table.setPageIndex(i)}
                className={`w-[40px] h-[40px] rounded-md text-white text-sm font-medium
                  ${isActive ? 'bg-[#797068]' : 'bg-gray-300'}`}
              >
                {i + 1}
              </button>
            )
          })}

          <button
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
            className={`w-[40px] h-[40px] rounded-md text-white text-sm font-medium
              ${
                table.getCanNextPage()
                  ? 'bg-[#797068]'
                  : 'bg-gray-300 cursor-not-allowed'
              }`}
          >
            {'>'}
          </button>
        </div>
      </div>
    </div>
  )
}
